function MarketingPanel({data,refresh}){const {run}=useProgress();const [coupon,setCoupon]=useState({code:'',type:'fixed',value:'',min_order:'',max_uses:'',active:true});const [zone,setZone]=useState({name:'',fee:'',min_order:'',active:true});const saveCoupon=async()=>{try{await run('جاري حفظ الكوبون…',()=>api('/admin/coupons',{method:'POST',body:JSON.stringify(coupon)}));setCoupon({code:'',type:'fixed',value:'',min_order:'',max_uses:'',active:true});await refresh()}catch(e){alert(e.message)}};const saveZone=async()=>{try{await run('جاري حفظ منطقة التوصيل…',()=>api('/admin/zones',{method:'POST',body:JSON.stringify(zone)}));setZone({name:'',fee:'',min_order:'',active:true});await refresh()}catch(e){alert(e.message)}};return <section className="panel"><div className="phase2-grid"><div><h2><Gift size={18}/> كوبونات الخصم</h2><div className="inline-form"><input placeholder="CODE" value={coupon.code} onChange={e=>setCoupon({...coupon,code:e.target.value.toUpperCase()})}/><select value={coupon.type} onChange={e=>setCoupon({...coupon,type:e.target.value})}><option value="fixed">مبلغ ثابت</option><option value="percent">نسبة %</option></select><input type="number" placeholder="القيمة" value={coupon.value} onChange={e=>setCoupon({...coupon,value:e.target.value})}/><input type="number" placeholder="الحد الأدنى" value={coupon.min_order} onChange={e=>setCoupon({...coupon,min_order:e.target.value})}/><input type="number" placeholder="عدد الاستخدامات" value={coupon.max_uses} onChange={e=>setCoupon({...coupon,max_uses:e.target.value})}/><button className="btn primary" onClick={saveCoupon}>إضافة</button></div><div className="simple-list">{data.coupons?.map(c=><div key={c.id}><b>{c.code}</b><span>{c.type==='percent'?`${c.value}%`:money(c.value)}</span><small>{c.used_count||0} استخدام</small></div>)}</div></div><div><h2><MapPinned size={18}/> مناطق التوصيل</h2><div className="inline-form"><input placeholder="اسم المنطقة" value={zone.name} onChange={e=>setZone({...zone,name:e.target.value})}/><input type="number" placeholder="رسم التوصيل" value={zone.fee} onChange={e=>setZone({...zone,fee:e.target.value})}/><input type="number" placeholder="الحد الأدنى" value={zone.min_order} onChange={e=>setZone({...zone,min_order:e.target.value})}/><button className="btn primary" onClick={saveZone}>إضافة</button></div><div className="simple-list">{data.zones?.map(z=><div key={z.id}><b>{z.name}</b><span>{money(z.fee)}</span><small>حد أدنى: {money(z.min_order)}</small></div>)}</div></div></div></section>}
function SideButton({icon,label,badge=0,active,onClick,show}){return show&&<button className={active?'side active':'side'} onClick={onClick}>{icon}<span className="side-label">{label}</span>{badge>0&&<em className="nav-badge" aria-label={`${badge} طلب جديد`}>{badge>99?'99+':badge}</em>}</button>}
function Orders({data,refresh}){
  const {run}=useProgress();
  const statuses={new:'جديد',confirmed:'مؤكد',preparing:'قيد التحضير',ready:'جاهز',delivered:'تم التسليم',cancelled:'ملغى'};
  const [statusFilter,setStatusFilter]=useState('all');
  const [dateFilter,setDateFilter]=useState('all');
  const [specificDate,setSpecificDate]=useState('');
  const [history,setHistory]=useState(null);
  const historyPanelRef=useRef(null);

  useEffect(()=>{
    if(!history)return;
    const timer=setTimeout(()=>{
      historyPanelRef.current?.scrollIntoView({behavior:'smooth',block:'start'});
    },60);
    return ()=>clearTimeout(timer);
  },[history]);

  const getOrderDate=order=>{
    const raw=String(order.created_at||'');
    const value=raw.endsWith('Z')||/[+-]\d\d:\d\d$/.test(raw)?raw:`${raw}Z`;
    const d=new Date(value);
    return Number.isNaN(d.getTime())?null:d;
  };
  const dateKey=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Beirut',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
  const todayKey=dateKey(new Date());
  const getBeirutParts=d=>{
    const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Beirut',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(d);
    return Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)]));
  };
  const matchesDate=order=>{
    if(dateFilter==='all')return true;
    const d=getOrderDate(order); if(!d)return false;
    const key=dateKey(d);
    if(dateFilter==='today')return key===todayKey;
    const today=new Date();
    const tp=getBeirutParts(today);
    const op=getBeirutParts(d);
    if(dateFilter==='yesterday'){
      const y=new Date(today.getTime()-24*60*60*1000);
      return key===dateKey(y);
    }
    if(dateFilter==='month')return op.year===tp.year&&op.month===tp.month;
    if(dateFilter==='week'){
      const todayDate=new Date(Date.UTC(tp.year,tp.month-1,tp.day));
      const mondayOffset=(todayDate.getUTCDay()+6)%7;
      const start=new Date(todayDate); start.setUTCDate(todayDate.getUTCDate()-mondayOffset);
      const end=new Date(start); end.setUTCDate(start.getUTCDate()+7);
      const orderDate=new Date(Date.UTC(op.year,op.month-1,op.day));
      return orderDate>=start&&orderDate<end;
    }
    if(dateFilter==='specific')return !!specificDate&&key===specificDate;
    return true;
  };
  const filteredOrders=useMemo(()=>data.orders.filter(o=>(statusFilter==='all'||o.status===statusFilter)&&matchesDate(o)),[data.orders,statusFilter,dateFilter,specificDate]);
  const resetFilters=()=>{setStatusFilter('all');setDateFilter('all');setSpecificDate('');};
  const statusChanged=async(id,status)=>{
    try{
      await run('جاري تحديث حالة الطلب…',()=>api('/admin/orders/'+id,{method:'PUT',body:JSON.stringify({status})}));
      await refresh();
    }catch(err){alert(err.message||'تعذر تحديث الحالة');}
  };
  const openHistory=async order=>{
    try{
      const result=await run('جاري تحميل سجل الطلب…',()=>api('/admin/orders/'+order.id+'/history'));
      setHistory({order,history:result.history||[]});
    }catch(err){alert(err.message||'تعذر تحميل سجل الطلب');}
  };
  return <section className="panel">
    <div className="orders-filters">
      <div className="filter-field"><label>الحالة</label><select value={statusFilter} onChange={e=>run('جاري تطبيق فلتر الحالة…',async()=>{setStatusFilter(e.target.value)})}><option value="all">كل الحالات</option>{Object.entries(statuses).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div>
      <div className="filter-field"><label>التاريخ</label><select value={dateFilter} onChange={e=>run('جاري تطبيق فلتر التاريخ…',async()=>{setDateFilter(e.target.value);if(e.target.value!=='specific')setSpecificDate('')})}><option value="all">كل التواريخ</option><option value="today">اليوم</option><option value="yesterday">البارحة</option><option value="week">الأسبوع الحالي</option><option value="month">الشهر الحالي</option><option value="specific">تاريخ محدد</option></select></div>
      {dateFilter==='specific'&&<div className="filter-field"><label>اختر التاريخ</label><input type="date" value={specificDate} onChange={e=>run('جاري تطبيق التاريخ…',async()=>{setSpecificDate(e.target.value)})}/></div>}
      <div className="orders-filter-summary"><b>{filteredOrders.length}</b><span>طلب</span></div>
      {(statusFilter!=='all'||dateFilter!=='all')&&<button className="btn ghost filter-reset" onClick={()=>run('جاري إعادة ضبط الفلاتر…',async()=>resetFilters())}>إعادة ضبط</button>}
    </div>
    <div className="status-legend">{Object.entries(statuses).map(([k,v])=><span key={k} className={`legend-item status-${k}`}><i></i>{v}</span>)}</div>
    <div className="table-wrap"><table><thead><tr><th>الطلب</th><th>الزبون</th><th>الأصناف</th><th>المجموع</th><th>الحالة</th><th>السجل</th><th>WhatsApp</th></tr></thead><tbody>
      {filteredOrders.length===0?<tr><td colSpan="7" className="empty-orders">لا توجد طلبات مطابقة للفلاتر المحددة.</td></tr>:filteredOrders.map(o=><tr key={o.id} className={`order-row status-row-${o.status||'new'}`}>
        <td><b>#{o.id}</b><small>{getOrderDate(o)?getOrderDate(o).toLocaleString('ar-LB',{timeZone:'Asia/Beirut'}):'—'}</small></td>
        <td><b>{o.customer_name}</b><small>{o.customer_phone}</small><small>{o.address}</small></td>
        <td>{o.items.map(i=><div key={i.itemId}>{i.name} × {i.quantity}</div>)}{o.notes&&<small>ملاحظة: {o.notes}</small>}</td>
        <td><div className="order-total-values"><b>{money(o.total,data.settings.currency)}</b><small>{moneyInWords(o.total,data.settings.currency)}</small></div></td>
        <td><select className={`status-select status-${o.status||'new'}`} value={o.status||'new'} onChange={e=>statusChanged(o.id,e.target.value)}>{Object.entries(statuses).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></td>
        <td><button className="icon-btn history-btn" title="سجل تغييرات الطلب" onClick={()=>openHistory(o)}><Clock size={16}/></button></td>
        <td>{o.whatsapp_sent?'✓ أُرسلت':'—'}</td>
      </tr>)}
    </tbody></table></div>
    {history&&<div ref={historyPanelRef} id="order-history-panel" className="order-history-panel">
      <div className="order-history-head"><div><span className="eyebrow">سجل الطلب</span><h3>الطلب #{history.order.id}</h3></div><button className="icon-btn" onClick={()=>setHistory(null)} title="إغلاق"><X size={17}/></button></div>
      {history.history.length===0?<p className="muted">لا يوجد سجل تغييرات لهذا الطلب حتى الآن.</p>:<div className="order-history-list">{history.history.map(h=><div className="order-history-entry" key={h.id}><div className={`history-status-dot status-${h.new_status}`}></div><div><b>{statuses[h.old_status]||h.old_status} → {statuses[h.new_status]||h.new_status}</b><small>{h.changed_by_name||'الإدارة'} · {new Date(h.changed_at).toLocaleString('ar-LB',{timeZone:'Asia/Beirut'})}</small></div></div>)}</div>}
    </div>}
  </section>;
}
function Items({data,refresh}){const {run}=useProgress();const [editing,setEditing]=useState(null),[kind,setKind]=useState('item'),[catEditing,setCatEditing]=useState(null),[catName,setCatName]=useState(''),[error,setError]=useState('');const save=async form=>{setError('');try{const path=kind==='item'?'/admin/items':'/admin/offers';const body=kind==='item'?{...form,price:Number(form.price),category_id:form.category_id||null,sort_order:Number(form.sort_order)||0,allergens:form.allergens||'',options_json:form.options_json||'[]'}:{...form,price:Number(form.price),sort_order:Number(form.sort_order)||0};await run(editing?.id?'جاري حفظ التعديل…':'جاري إضافة الصنف…',()=>api(editing?.id?path+'/'+editing.id:path,{method:editing?.id?'PUT':'POST',body:JSON.stringify(body)}));setEditing(null);await refresh()}catch(e){setError(e.message)}};const deleteThing=async(x)=>{if(!confirm(`هل أنت متأكد من حذف ${kind==='item'?'الصنف':'العرض'}؟`))return;try{await run('جاري حذف العنصر…',()=>api((kind==='item'?'/admin/items/':'/admin/offers/')+x.id,{method:'DELETE'}));await refresh()}catch(e){setError(e.message)}};const saveCat=async()=>{if(!catName.trim())return;try{await run(catEditing?.id?'جاري حفظ التصنيف…':'جاري إضافة التصنيف…',()=>api(catEditing?.id?'/admin/categories/'+catEditing.id:'/admin/categories',{method:catEditing?.id?'PUT':'POST',body:JSON.stringify({name:catName.trim()})}));setCatEditing(null);setCatName('');await refresh()}catch(e){setError(e.message)}};const deleteCat=async c=>{if(!confirm(`حذف التصنيف «${c.name}»؟ الأصناف التابعة له ستبقى بدون تصنيف.`))return;try{await run('جاري حذف التصنيف…',()=>api('/admin/categories/'+c.id,{method:'DELETE'}));await refresh()}catch(e){setError(e.message)}};return <section className="panel"><div className="toolbar"><div className="seg"><button className={kind==='item'?'on':''} onClick={()=>setKind('item')}>الأصناف</button><button className={kind==='offer'?'on':''} onClick={()=>setKind('offer')}>العروض</button></div><button className="btn primary" onClick={()=>run('جاري فتح نموذج الإضافة…',async()=>{setEditing(kind==='item'?{category_id:data.categories[0]?.id||'',name:'',description:'',price:'',image:'',available:true,featured:false,sort_order:(data.items?.length||0)+1}:{title:'',description:'',price:'',image:'',active:true,sort_order:(data.offers?.length||0)+1})})}><Plus/> إضافة {kind==='item'?'صنف':'عرض'}</button></div>{error&&<div className="error admin-error">{error}</div>}{editing&&<Editor type={kind} value={editing} categories={data.categories} onCancel={()=>setEditing(null)} onSave={save}/>}<div className="admin-section-title"><div><Tags size={18}/><h2>التصنيفات</h2></div><button className="btn ghost" onClick={()=>run('جاري فتح نموذج التصنيف…',async()=>{setCatEditing({});setCatName('')})}><Plus size={17}/> إضافة تصنيف</button></div><div className="category-list">{data.categories.map(c=><div className="category-admin" key={c.id}><span>{c.name}</span><div><button className="icon-btn" onClick={()=>run('جاري فتح تعديل التصنيف…',async()=>{setCatEditing(c);setCatName(c.name)})}><Edit3 size={16}/></button><button className="icon-btn danger" onClick={()=>deleteCat(c)}><Trash2 size={16}/></button></div></div>)}</div>{catEditing&&<div className="category-editor"><input autoFocus placeholder="اسم التصنيف" value={catName} onChange={e=>setCatName(e.target.value)}/><button className="btn primary" onClick={saveCat}>حفظ</button><button className="btn ghost" onClick={()=>setCatEditing(null)}>إلغاء</button></div>}<div className="admin-grid">{(kind==='item'?data.items:data.offers).map(x=><div className="admin-card admin-product-card" key={x.id}>{x.image?<img className="admin-card-image" src={x.image} alt={kind==='item'?x.name:x.title}/>:<div className="admin-image-placeholder"><ImageIcon size={28}/><span>لا توجد صورة</span></div>}<div className="card-top"><span className="status-dot">{kind==='item'?(x.available?'متاح':'مخفي'):(x.active?'فعال':'متوقف')}</span><div className="card-actions"><button className="icon-btn" onClick={()=>run('جاري فتح التعديل…',async()=>{setEditing(x)})} title="تعديل"><Edit3 size={17}/></button><button className="icon-btn danger" onClick={()=>deleteThing(x)} title="حذف"><Trash2 size={17}/></button></div></div><div className="admin-product-info"><h3>{kind==='item'?x.name:x.title}</h3>{kind==='item'&&<small className="category-name">{data.categories.find(c=>Number(c.id)===Number(x.category_id))?.name||'بدون تصنيف'}</small>}<p>{kind==='item'?x.description:x.description}</p><strong>{money(x.price,data.settings.currency)}</strong></div></div>)}</div></section>}
function Editor({type,value,categories,onCancel,onSave}){
  const {run}=useProgress();
  const [f,setF]=useState(value);
  const [uploading,setUploading]=useState(false);
  const [uploadError,setUploadError]=useState('');
  const set=(k,v)=>setF({...f,[k]:v});
  const uploadImage=async e=>{
    const file=e.target.files?.[0];
    if(!file)return;
    setUploadError('');
    if(!file.type.startsWith('image/')){setUploadError('يرجى اختيار ملف صورة.');return;}
    if(file.size>4*1024*1024){setUploadError('حجم الصورة يجب ألا يتجاوز 4MB.');return;}
    setUploading(true);
    try{
      const dataUrl=await new Promise((resolve,reject)=>{
        const reader=new FileReader(); reader.onload=()=>resolve(reader.result); reader.onerror=reject; reader.readAsDataURL(file);
      });
      const result=await run('جاري رفع الصورة…',()=>api('/admin/upload-image',{method:'POST',body:JSON.stringify({dataUrl,fileName:file.name})}));
      set('image',result.url);
    }catch(err){setUploadError(err.message||'تعذر رفع الصورة');}
    finally{setUploading(false);}
    e.target.value='';
  };
  return <div className="editor"><div className="editor-head"><b>{value.id?'تعديل':'إضافة'} {type==='item'?'صنف':'عرض'}</b><button onClick={onCancel}><X/></button></div>
    {type==='item'&&<select value={f.category_id||''} onChange={e=>set('category_id',e.target.value)}><option value="">بدون تصنيف</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>}
    <input placeholder={type==='item'?'اسم الصنف':'عنوان العرض'} value={f.name||f.title||''} onChange={e=>set(type==='item'?'name':'title',e.target.value)}/>
    <textarea placeholder="الوصف" value={f.description||''} onChange={e=>set('description',e.target.value)}/>{type==='item'&&<><input placeholder="مسببات الحساسية" value={f.allergens||''} onChange={e=>set('allergens',e.target.value)}/><textarea placeholder='خيارات التخصيص JSON: [{"name":"جبنة إضافية","price":50000}]' value={f.options_json||'[]'} onChange={e=>set('options_json',e.target.value)}/></>}
    <input type="number" placeholder="السعر" value={f.price??''} onChange={e=>set('price',e.target.value)}/><label className="sort-order-field"><span>ترتيب الظهور</span><input type="number" min="0" step="1" placeholder="مثلاً 1" value={f.sort_order??0} onChange={e=>set('sort_order',e.target.value)}/><small>الرقم الأصغر يظهر أولاً.</small></label>
    <label className="image-upload-field"><span>صورة {type==='item'?'الصنف':'العرض'}</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={uploadImage} disabled={uploading}/><small>{uploading?'جاري رفع الصورة…':'اختر صورة من الجهاز (حتى 4MB)'}</small></label>
    <input placeholder="رابط الصورة (اختياري)" value={f.image||''} onChange={e=>set('image',e.target.value)}/>
    {uploadError&&<div className="error">{uploadError}</div>}
    {f.image?<div className="image-preview"><img src={f.image} alt="معاينة" onError={e=>e.currentTarget.style.display='none'}/><span>معاينة الصورة</span></div>:null}
    <div className="checks">{type==='item'?<><label><input type="checkbox" checked={!!f.available} onChange={e=>set('available',e.target.checked)}/> متاح</label><label><input type="checkbox" checked={!!f.featured} onChange={e=>set('featured',e.target.checked)}/> مميز</label></>:<label><input type="checkbox" checked={!!f.active} onChange={e=>set('active',e.target.checked)}/> فعال</label>}</div>
    <div className="editor-actions"><button className="btn primary" disabled={uploading} onClick={()=>onSave(f)}>حفظ</button><button className="btn ghost" onClick={onCancel}>إلغاء</button></div>
  </div>
}
function SettingsPanel({data,refresh}){const {run}=useProgress();const [f,setF]=useState({...data.settings});const [logoBusy,setLogoBusy]=useState(false);const [logoError,setLogoError]=useState('');const [waTest,setWaTest]=useState('');const save=async()=>{await run('جاري حفظ إعدادات الموقع…',()=>api('/admin/settings',{method:'PUT',body:JSON.stringify(f)}));applyTheme(f);await refresh()};const uploadLogo=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;setLogoError('');if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type)){setLogoError('استخدم JPG أو PNG أو WEBP أو GIF.');return}if(file.size>4*1024*1024){setLogoError('حجم الشعار يجب ألا يتجاوز 4MB.');return}setLogoBusy(true);try{const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('تعذر قراءة الملف.'));r.readAsDataURL(file)});const result=await run('جاري رفع الشعار…',()=>api('/admin/upload-logo',{method:'POST',body:JSON.stringify({dataUrl,fileName:file.name})}));setF(x=>({...x,logoUrl:result.url}))}catch(err){setLogoError(err.message||'تعذر رفع الشعار.')}finally{setLogoBusy(false)}};return <section className="panel settings-panel"><h2>هوية الموقع</h2><div className="form-grid"><label>اسم الموقع<input value={f.siteName||''} onChange={e=>setF({...f,siteName:e.target.value})}/></label><div className="logo-upload-block"><label>الشعار / رابط الصورة<input value={f.logoUrl||''} onChange={e=>setF({...f,logoUrl:e.target.value})}/></label><label className="image-upload-field logo-upload-field"><span>أو اختر الشعار من جهازك</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" disabled={logoBusy} onChange={uploadLogo}/><small>{logoBusy?'جاري رفع الشعار…':'يمكنك اختيار صورة مباشرة من الهاتف أو الكمبيوتر.'}</small></label>{logoError&&<div className="error">{logoError}</div>}{f.logoUrl&&<div className="logo-preview"><img src={f.logoUrl} alt="معاينة الشعار"/><button type="button" className="btn ghost" disabled={logoBusy} onClick={()=>setF(x=>({...x,logoUrl:''}))}>إزالة الشعار</button></div>}</div><label>الوصف المختصر<input value={f.tagline||''} onChange={e=>setF({...f,tagline:e.target.value})}/></label><label>رقم الهاتف / WhatsApp<input value={f.phone||''} onChange={e=>setF({...f,phone:e.target.value})}/></label><label>العملة<input value={f.currency||''} onChange={e=>setF({...f,currency:e.target.value})}/></label></div><h2>الثيم والمناسبة</h2><div className="theme-grid">{Object.entries(themes).map(([k,t])=><button key={k} className={f.theme===k?'theme selected':'theme'} onClick={()=>setF({...f,theme:k,primary:t.primary,secondary:t.secondary,background:t.background})}><span style={{background:t.primary}}></span><b>{t.label}</b></button>)}</div><div className="custom-colors"><label>اللون الأساسي<input type="color" value={f.primary||'#9a3412'} onChange={e=>setF({...f,primary:e.target.value,theme:'custom'})}/></label><label>اللون الثانوي<input type="color" value={f.secondary||'#f59e0b'} onChange={e=>setF({...f,secondary:e.target.value,theme:'custom'})}/></label><label>لون الخلفية<input type="color" value={f.background||'#fffaf3'} onChange={e=>setF({...f,background:e.target.value,theme:'custom'})}/></label></div><button className="btn primary" onClick={save}>حفظ التغييرات</button></section>}
function UsersPanel({data,refresh,canAddAdmin}){const {run}=useProgress();const [editing,setEditing]=useState(null);const save=async f=>{try{await run(f.id?'جاري حفظ تعديل المستخدم…':'جاري إضافة المستخدم…',()=>api('/admin/users'+(f.id?'/'+f.id:''),{method:f.id?'PUT':'POST',body:JSON.stringify(f)}));setEditing(null);await refresh()}catch(e){throw e}};return <section className="panel"><div className="toolbar"><span>يمكنك تحديد الصلاحيات لكل موظف.</span><button className="btn primary" onClick={()=>setEditing({name:'',email:'',password:'',role:'staff',permissions:['RECEIVE_ORDERS'],active:true})}><Plus/> مستخدم جديد</button></div>{editing&&<UserEditor value={editing} canAddAdmin={canAddAdmin} onCancel={()=>setEditing(null)} onSave={save}/>}<div className="user-list">{data.users.map(u=><div className="user-card" key={u.id}><div className="avatar">{u.name?.[0]||'م'}</div><div><b>{u.name}</b><span>{u.email}</span><small>{u.role==='admin'?'مدير كامل':u.permissions.map(p=>perms.find(x=>x[0]===p)?.[1]).filter(Boolean).join(' • ')}</small></div><div className="user-actions"><span className={u.active?'active-text':'muted'}>{u.active?'فعال':'موقوف'}</span><button className="icon-btn" onClick={()=>setEditing({...u,password:''})}><Edit3 size={17}/></button></div></div>)}</div></section>}
function UserEditor({value,canAddAdmin,onCancel,onSave}){const [f,setF]=useState(value);const [confirmPassword,setConfirmPassword]=useState('');const [error,setError]=useState('');const toggle=p=>setF({...f,permissions:f.permissions.includes(p)?f.permissions.filter(x=>x!==p):[...f.permissions,p]});const save=async()=>{setError('');if(!f.id&&!f.password){setError('كلمة المرور مطلوبة.');return}if(f.password&&f.password.length<10){setError('كلمة المرور يجب أن تكون 10 أحرف على الأقل.');return}if(f.password!==confirmPassword){setError('كلمتا المرور غير متطابقتين.');return}if(f.role==='admin'&&!canAddAdmin){setError('لا تملك صلاحية إضافة مدير.');return}try{await onSave(f)}catch(e){setError(e?.message||'تعذر حفظ المستخدم.')}};return <div className="editor"><div className="editor-head"><b>{f.id?'تعديل المستخدم':'إضافة مستخدم'}</b><button onClick={onCancel}><X/></button></div>{error&&<div className="user-form-error" role="alert" aria-live="polite">{error}</div>}<input placeholder="الاسم" value={f.name} onChange={e=>{setF({...f,name:e.target.value});setError('')}}/><input type="email" placeholder="البريد" value={f.email} onChange={e=>{setF({...f,email:e.target.value});setError('')}}/><input type="password" placeholder={f.id?'كلمة مرور جديدة (اختياري)':'كلمة المرور'} value={f.password} onChange={e=>{setF({...f,password:e.target.value});setError('')}} autoComplete="new-password" minLength={10}/>{(f.password||!f.id)&&<input type="password" placeholder="مطابقة كلمة المرور" value={confirmPassword} onChange={e=>{setConfirmPassword(e.target.value);setError('')}} autoComplete="new-password" minLength={10}/>}<label>الدور<select value={f.role} onChange={e=>setF({...f,role:e.target.value})}><option value="staff">موظف</option>{canAddAdmin&&<option value="admin">مدير كامل</option>}</select></label><div className="perm-box">{perms.map(([p,l])=><label key={p}><input type="checkbox" checked={f.role==='admin'||f.permissions.includes(p)} disabled={f.role==='admin'||(p==='ADD_ADMIN'&&!canAddAdmin)} onChange={()=>toggle(p)}/>{l}</label>)}</div><label><input type="checkbox" checked={!!f.active} onChange={e=>setF({...f,active:e.target.checked})}/> الحساب فعال</label><div className="editor-actions"><button className="btn primary" onClick={save}>حفظ</button><button className="btn ghost" onClick={onCancel}>إلغاء</button></div></div>}
function App(){const isAdmin=location.pathname.startsWith('/admin');const [logged,setLogged]=useState(null);useEffect(()=>{if(!isAdmin){setLogged(true);return}api('/auth/me').then(()=>setLogged(true)).catch(()=>setLogged(false));},[isAdmin]);useEffect(()=>{if(isAdmin)document.title='لوحة الإدارة | فرنية صاج';},[isAdmin]);if(isAdmin){if(logged===null)return <div className="loader">جاري التحقق من الجلسة…</div>;return logged?<Admin/>:<Login onLogin={()=>setLogged(true)}/>}return <Home/>}
createRoot(document.getElementById('root')).render(<ProgressProvider><App/></ProgressProvider>);
